  '1h333nq85ni': R`<p>برای گرد کردن تا یک جایگاه، به رقمِ <b>درست بعد از آن</b> (سمت راستِ آن) نگاه کنید.</p><ul><li>5 یا بیشتر: رو به <b>بالا</b> گرد کنید (یکی به رقمِ آن جایگاه اضافه کنید).</li><li>4 یا کمتر: رو به <b>پایین</b> گرد کنید (رقمِ آن جایگاه تغییر نمی‌کند).</li></ul><p>همهٔ رقم‌های بعد از جایگاه گرد کردن صفر می‌شوند.</p>`,
  '264ckm0rxdd': R`<p>عدد 3,462 را تا صدگان گرد کنید.</p><ol><li>رقم صدگان 4 است. رقم بعد از آن (دهگان) 6 است.</li><li>6 از 5 کمتر نیست، پس رو به بالا گرد می‌کنیم: 4 به 5 تبدیل می‌شود.</li><li>پاسخ: <b>3,500</b>.</li></ol><p>اگر تا دهگان گرد کنیم، 3,462 می‌شود 3,460 و اگر تا یکان هزار گرد کنیم، 3,000.</p>`,
