  '2crp1hgq6k1': R`
<p>جمع مقدارها را روی هم می‌گذارد؛ تفریق باقی‌مانده یا <b>تفاضل</b> دو مقدار را پیدا می‌کند. برای عددهای بزرگ از <b>روش ستونی</b> استفاده می‌کنیم: رقم‌ها را بر اساس ارزش مکانی زیر هم می‌نویسیم و از ستون یکان به سمت چپ پیش می‌رویم.</p>
<h3>جمع با انتقال</h3>
<p>اگر حاصل یک ستون 10 یا بیشتر شد، رقم یکانِ آن را می‌نویسیم و ده را به ستون بعدی <b>منتقل می‌کنیم</b> (یک «دَه بر یک»).</p>
⟦0⟧
<h3>تفریق با قرض گرفتن</h3>
<p>اگر رقم بالای یک ستون از رقم پایینی کوچک‌تر بود، از ستون بعدی یکی <b>قرض می‌گیریم</b>: این کار 10 به ستون فعلی اضافه می‌کند.</p>
⟦1⟧
⟦2⟧
<h3>مسئله‌های کلامی</h3>
<p>واژه‌هایی مانند <i>روی هم، در مجموع، بیشتر، افزایش</i> معمولاً یعنی جمع. واژه‌هایی مانند <i>باقی ماند، مانده، تفاوت، چقدر بیشتر، کمتر</i> معمولاً یعنی تفریق. همیشه از خودتان بپرسید مسئله واقعاً چه می‌خواهد.</p>
⟦3⟧`,
  '12bc1hhhzgf': R`<p>$4{,}587 + 2{,}846$</p><ol><li>یکان: $7 + 6 = 13$ ← 3 را می‌نویسیم و 1 را منتقل می‌کنیم.</li><li>دهگان: $8 + 4 + 1 = 13$ ← 3 را می‌نویسیم و 1 را منتقل می‌کنیم.</li><li>صدگان: $5 + 8 + 1 = 14$ ← 4 را می‌نویسیم و 1 را منتقل می‌کنیم.</li><li>یکان هزار: $4 + 2 + 1 = 7$.</li></ol><p>پاسخ: <b>7,433</b>.</p>`,
  'dzfcdnot25': R`<p>$6{,}204 - 1{,}758$</p><ol><li>یکان: 4 از 8 کوچک‌تر است. رقم دهگان 0 است، پس از صدگان قرض می‌گیریم: 204 می‌شود 1 صدتایی، 9 دهتایی و 14 یکی. $14 - 8 = 6$.</li><li>دهگان: $9 - 5 = 4$.</li><li>صدگان: 1 از 7 کوچک‌تر است، پس یک هزارتایی قرض می‌گیریم: $11 - 7 = 4$.</li><li>یکان هزار: $5 - 1 = 4$.</li></ol><p>پاسخ: <b>4,446</b>.</p>`,
  '1myl5xbp4pm': R`<p>جمع و تفریق عکس یکدیگرند. تفریق را با جمع امتحان کنید: $4{,}446 + 1{,}758 = 6{,}204$ ✓. با همین روش عدد مجهول هم پیدا می‌شود: اگر $\square + 348 = 1{,}000$، آنگاه $\square = 1{,}000 - 348 = 652$.</p>`,
  '23w41b37di3': R`<p>اشتباه رایج این است که در هر ستون رقم کوچک‌تر را از بزرگ‌تر کم کنیم (مثلاً بنویسیم $52 - 38 = 26$). باید قرض گرفت: $52 - 38 = 14$.</p>`,
  'jzpsrz7qv': R`حاصل $⟦0⟧ + ⟦1⟧$ را حساب کنید.`,
  '11vnennk127': R`رقم‌ها را بر اساس ارزش مکانی زیر هم بنویسید و از یکان جمع کنید؛ هر جا ستونی به 10 یا بیشتر رسید، یکی به ستون بعد منتقل کنید: $⟦0⟧ + ⟦1⟧ = ⟦2⟧$.`,
  '2cqlmyuanc4': R`حاصل $⟦0⟧ - ⟦1⟧$ را حساب کنید.`,
  '217um699krb': R`ستون به ستون از یکان کم کنید و هر جا رقم بالا کوچک‌تر بود قرض بگیرید: $⟦0⟧ - ⟦1⟧ = ⟦2⟧$. امتحان: $⟦3⟧ + ⟦4⟧ = ⟦5⟧$.`,
  '20q2iwal3wx': R`چه عددی در مربع قرار می‌گیرد؟ $\square + ⟦0⟧ = ⟦1⟧$`,
  '2vzsixgbwq': R`تفریق عکس جمع است: $⟦0⟧ - ⟦1⟧ = ⟦2⟧$.`,
  '19k8gxx8enm': R`یک کتابخانه ⟦0⟧ کتاب داشت. ⟦1⟧ کتاب تازه به آن رسید و سپس ⟦2⟧ کتاب امانت داده شد. چند کتاب در کتابخانه مانده است؟`,
  '22c2nbk22nn': R`کتاب‌های تازه را اضافه و کتاب‌های امانت‌داده‌شده را کم کنید: $⟦0⟧ + ⟦1⟧ - ⟦2⟧ = ⟦3⟧$.`,
