  '1rjytzik9fa': R`<p>ضرب و تقسیم عکس یکدیگرند: $4 \times 6 = 24 \iff 24 \div 6 = 4$.</p><ul><li>در ضرب ترتیب مهم نیست: $a \times b = b \times a$.</li><li>ضرب روی جمع پخش می‌شود: $a \times (b + c) = a \times b + a \times c$.</li></ul>`,
  '11dzvmewikb': R`47 \div 5 = 9 \text{ و باقی‌مانده } 2 \qquad \text{زیرا } 5 \times 9 + 2 = 47`,
  '1z8tho01ahp': R`<p>150 دانش‌آموز به اردو می‌روند. هر اتوبوس 40 نفر جا دارد. چند اتوبوس لازم است؟</p><p>$150 \div 40 = 3$ و باقی‌مانده 30. سه اتوبوس 120 نفر را می‌برند؛ 30 نفر باقی‌مانده هم اتوبوس لازم دارند، پس <b>4 اتوبوس</b> لازم است.</p>`,
  '1g33a99esai': R`<p>در مسئله‌های کلامی، معنای باقی‌مانده را مشخص کنید. «چند اتوبوس <i>لازم است</i>؟» یعنی رو به بالا گرد کنید؛ «چند جعبه <i>کاملاً</i> پر می‌شود؟» یعنی رو به پایین.</p>`,
  '10v4h321li3': R`حاصل $⟦0⟧ \times ⟦1⟧$ را حساب کنید.`,
  'h89yrotk3q': R`$⟦0⟧ \times ⟦1⟧ = ⟦2⟧$؛ یعنی ⟦3⟧ دستهٔ ⟦4⟧تایی.`,
  '2gi38wc5lfl': R`⟦0⟧ را به صورت ⟦1⟧ + ⟦2⟧ بشکنید: $⟦3⟧ \times ⟦4⟧ + ⟦5⟧ \times ⟦6⟧ = ⟦7⟧ + ⟦8⟧ = ⟦9⟧$.`,
  '2g99zk4sonb': R`حاصل $⟦0⟧ \div ⟦1⟧$ را حساب کنید.`,
  'cggzswltjw': R`تقسیم عکس ضرب است: $⟦0⟧ \times ⟦1⟧ = ⟦2⟧$، پس $⟦3⟧ \div ⟦4⟧ = ⟦5⟧$.`,
  '7njwte8n8l': R`باقی‌ماندهٔ تقسیم ⟦0⟧ بر ⟦1⟧ چند است؟`,
  '1c2kbih8aei': R`$⟦0⟧ \times ⟦1⟧ = ⟦2⟧$ و $⟦3⟧ - ⟦4⟧ = ⟦5⟧$، پس $⟦6⟧ \div ⟦7⟧ = ⟦8⟧$ و باقی‌مانده <b>⟦9⟧</b>.`,
  '23lffvpxlg2': R`تخم‌مرغ`,
  'isjmxkkk5m': R`کاپ‌کیک`,
  'qd054tvbk9': R`مداد`,
  '22kysml68r1': R`بطری`,
  '29eftju2pbv': R`قرار است ⟦0⟧ ⟦1⟧ را در جعبه‌هایی بگذاریم که در هر کدام ⟦2⟧ عدد جا می‌شود. برای جا دادن همهٔ آن‌ها چند جعبه لازم است؟`,
  '1pnydk75epc': R`یک فروشگاه ⟦0⟧ ⟦1⟧ را در جعبه‌های ⟦2⟧تایی بسته‌بندی می‌کند. چند جعبه <b>کاملاً</b> پر می‌شود؟`,
  '9w986eh8jp': R`$⟦0⟧ \div ⟦1⟧ = ⟦2⟧$ و باقی‌مانده ⟦3⟧. ⟦4⟧`,
  'dnbly4c6lj': R`⟦0⟧ ⟦1⟧ باقی‌مانده هم جعبه لازم دارند، پس <b>⟦2⟧</b> جعبه لازم است.`,
  'doig2i1un2': R`فقط <b>⟦0⟧</b> جعبه پر می‌شود و ⟦1⟧ ⟦2⟧ باقی می‌ماند.`,
  '5ki7426a69': R`در یک سالن ⟦0⟧ ردیف صندلی هست و در هر ردیف ⟦1⟧ صندلی. روی هم چند صندلی وجود دارد؟`,
  '13ytah9dyhs': R`ردیف‌های مساوی یعنی ضرب: $⟦0⟧ \times ⟦1⟧ = ⟦2⟧$ صندلی.`,

