  'sxhmc0c8k9': R`<p><b>بزرگ‌ترین مقسوم‌علیه مشترک</b> (ب.م.م) بزرگ‌ترین عددی است که هر دو عدد را می‌شمارد. <b>کوچک‌ترین مضرب مشترک</b> (ک.م.م) کوچک‌ترین عددی است که مضرب هر دو عدد است.</p><p>با تجزیه به عامل‌های اول: ب.م.م هر عامل اولِ مشترک را با <b>کوچک‌ترین</b> توانش برمی‌دارد؛ ک.م.م همهٔ عامل‌های اول را با <b>بزرگ‌ترین</b> توانشان برمی‌دارد.</p>`,
  '2dcgjf0y6e9': R`<p>$24 = 2^3 \times 3$ و $36 = 2^2 \times 3^2$.</p><p>ب.م.م $= 2^2 \times 3 = 12$. &nbsp; ک.م.م $= 2^3 \times 3^2 = 72$.</p><p>امتحان: حاصل‌ضرب ب.م.م در ک.م.م برابر $12 \times 72 = 864 = 24 \times 36$ است ✓ (برای دو عدد همیشه درست است).</p>`,
  '13dl2xstaq0': R`<p>مسئله‌های ب.م.م دربارهٔ <i>تقسیم به دسته‌های مساوی</i> هستند (بزرگ‌ترین اندازهٔ دسته). مسئله‌های ک.م.م دربارهٔ <i>چیزهایی که دوباره هم‌زمان رخ می‌دهند</i> هستند (اولین باری که چرخه‌ها با هم جور می‌شوند).</p>`,
  '1v4c3frqq3d': R`بزرگ‌ترین مقسوم‌علیه مشترک (ب.م.م) دو عدد ⟦0⟧ و ⟦1⟧ چیست؟`,
  '8l33q80f9g': R`شمارنده‌های ⟦0⟧: ⟦1⟧.<br>شمارنده‌های ⟦2⟧: ⟦3⟧.<br>بزرگ‌ترین شمارندهٔ مشترک <b>⟦4⟧</b> است.`,
  'slhedaglcs': R`کوچک‌ترین مضرب مشترک (ک.م.م) دو عدد ⟦0⟧ و ⟦1⟧ چیست؟`,
  '1gi8rsfc6pi': R`مضرب‌های ⟦0⟧: ⟦1⟧، …<br>مضرب‌های ⟦2⟧: ⟦3⟧، …<br>اولین مضرب مشترک <b>⟦4⟧</b> است.`,
  '15d9oj1fzj1': R`کدام‌یک از این عددها <b>اول</b> است؟`,
  'xvmwee4nwk': R`⟦0⟧ دقیقاً دو شمارنده دارد: 1 و ⟦1⟧. بقیه مرکب‌اند: ⟦2⟧.`,
  '151txls1vlc': R`عدد ⟦0⟧ چند شمارنده دارد؟`,
  '1tllv5888z': R`جفت‌های شمارنده را بنویسید: ⟦0⟧. شمارنده‌ها ⟦1⟧ هستند؛ یعنی <b>⟦2⟧</b> شمارنده.`,
  'rjpmb07v6a': R`تجزیهٔ عدد ⟦0⟧ به عامل‌های اول چیست؟`,
  '162lv91sf8i': R`پشت سر هم بر عددهای اول تقسیم کنید: ⟦0⟧ = ⟦1⟧. همهٔ عامل‌ها اول‌اند و حاصل‌ضربشان دوباره ⟦2⟧ می‌شود.`,
  '1dcblj5tqu6': R`هانا ⟦0⟧ مهرهٔ قرمز و ⟦1⟧ مهرهٔ آبی دارد. او با همهٔ مهره‌ها دستبندهای یکسانی می‌سازد که در هر کدام تعداد مهره‌های قرمز یکسان و تعداد مهره‌های آبی هم یکسان است. او حداکثر چند دستبند می‌تواند بسازد؟`,
  '16f0mrep69j': R`هم ⟦0⟧ و هم ⟦1⟧ باید بر تعداد دستبندها بخش‌پذیر باشند، پس ب.م.م را پیدا می‌کنیم: ب.م.م دو عدد ⟦2⟧ و ⟦3⟧ برابر ⟦4⟧ است. او می‌تواند <b>⟦5⟧</b> دستبند بسازد که هر کدام ⟦6⟧ مهرهٔ قرمز و ⟦7⟧ مهرهٔ آبی دارد.`,
  '76jyl5vip0': R`دو چراغ همین حالا با هم چشمک زدند. یکی هر ⟦0⟧ ثانیه یک بار و دیگری هر ⟦1⟧ ثانیه یک بار چشمک می‌زند. چند ثانیهٔ دیگر دوباره با هم چشمک می‌زنند؟`,
  '2ddehafzm6d': R`ثانیه`,
  '1mfkmnfob4d': R`آن‌ها در مضرب‌های مشترک ⟦0⟧ و ⟦1⟧ با هم چشمک می‌زنند. اولین آن‌ها ک.م.م است: <b>⟦2⟧</b> ثانیه.`,
