  'sceh7pz7y9': R`<p>ضریب $n$ در فرمول جملهٔ عمومی، قدر نسبت است — نه جملهٔ اول.</p>`,
  '73l5vk6u1l': R`جملهٔ بعدیِ دنبالهٔ ⟦0⟧, … چیست؟`,
  '273m8h7rqm0': R`قدر نسبت ⟦0⟧ است، پس جملهٔ بعدی $⟦1⟧ ⟦2⟧ = ⟦3⟧$ است.`,
  'e7rskm3cuq': R`جملهٔ $u_{⟦0⟧}$ از دنبالهٔ ⟦1⟧, … را پیدا کنید.`,
  '1zj05x9ucbg': R`کدام فرمول جملهٔ عمومیِ ⟦0⟧, … را می‌دهد؟`,
  '10p4kmsov0h': R`جمله‌ها ⟦0⟧تا ⟦0⟧تا زیاد می‌شوند، پس فرمول با $⟦1⟧n$ شروع می‌شود. برای $n = 1$، از $⟦2⟧(1) + c = ⟦3⟧$ داریم $c = ⟦4⟧$: $u_n = ⟦5⟧$.`,
  'kmsujsbacm': R`هر جمله در ⟦0⟧ ضرب می‌شود، پس جملهٔ بعدی $⟦1⟧ \times ⟦2⟧ = ⟦3⟧$ است.`,
  '1tqcntwvtfu': R`کدام جملهٔ دنبالهٔ ⟦0⟧, … برابر ⟦1⟧ است؟`,
