  'f54rct691f': R`<p>مثلث‌های $ABC$ و $PQR$ متشابه‌اند و $AB = 6$، $BC = 8$ و $PQ = 9$. نسبت تشابه $k = \frac{9}{6} = 1.5$، پس $QR = 8 \times 1.5 = 12$. اگر مساحت مثلث $ABC$ برابر 24 باشد، مساحت مثلث $PQR$ برابر $24 \times 1.5^2 = 54$ است.</p>`,
