  '2v9wp16hr5': R`$⟦0⟧$ مثبت است، پس دو ریشهٔ حقیقی متمایز وجود دارد.`,
  '1awtt37lduc': R`$⟦0⟧$ صفر است، پس یک ریشهٔ حقیقی مضاعف وجود دارد.`,
  '1b3c8vdz0p': R`$⟦0⟧$ منفی است، پس ریشهٔ حقیقی وجود ندارد.`,
  '13khpmu10gc': R`مجموع ریشه‌های $⟦0⟧ = 0$ را پیدا کنید.`,
  '23qtrsvpbqj': R`مجموع ریشه‌ها $= -\frac{b}{a} = ⟦0⟧$.`,
  '2e310dsl6wd': R`حاصل‌ضرب ریشه‌های $⟦0⟧ = 0$ را پیدا کنید.`,
