  '1mojcap1eui': R`یک نظرسنجی این نتایج را داد.⟦0⟧یک نفر به تصادف انتخاب می‌شود. اگر بدانیم در گروه «⟦1⟧» است، احتمال اینکه در «⟦2⟧» باشد چقدر است؟`,
  '1461hv2wfqt': R`فقط ⟦0⟧ نفرِ «⟦1⟧» را در نظر بگیرید: $P = \frac{⟦2⟧}{⟦3⟧} = ⟦4⟧$.`,
  '12180tm9why': R`یک نظرسنجی این نتایج را داد.⟦0⟧یک نفر به تصادف انتخاب می‌شود. اگر بدانیم در «⟦1⟧» است، احتمال اینکه در گروه «⟦2⟧» باشد چقدر است؟`,
  'eppqyrg22a': R`یک تاس سالم ⟦0⟧ بار پرتاب می‌شود. احتمال آمدن دست‌کم یک شش چقدر است؟`,
  'wzrge9rclz': R`$1 - P(\text{هیچ شش}) = 1 - \left(\frac{5}{6}\right)^{⟦0⟧} = 1 - \frac{⟦1⟧}{⟦2⟧} = ⟦3⟧$.`,
  '1sg12en11ty': R`بیماری‌ای ⟦0⟧% مردم را مبتلا می‌کند. آزمایشی آن را در ⟦1⟧% بیماران تشخیص می‌دهد، اما برای ⟦2⟧% افراد سالم هم نتیجهٔ مثبت می‌دهد. اگر آزمایش کسی مثبت باشد، احتمال بیمار بودن او چقدر است؟ تا 3 رقم اعشار گرد کنید.`,
  '1n6kg7z10yy': R`کیسه‌ای ⟦0⟧ ژتون قرمز و ⟦1⟧ ژتون آبی دارد. یک ژتون بیرون آورده، برگردانده می‌شود و ژتون دوم بیرون آورده می‌شود. احتمال اینکه اولی قرمز و دومی آبی باشد چقدر است؟`,
  '29cd8gay3w4': R`با جای‌گذاری، دو برداشت مستقل‌اند: $\frac{⟦0⟧}{⟦1⟧} \times \frac{⟦2⟧}{⟦3⟧} = ⟦4⟧$.`,

