  '12p1gvv8rrs': R`
⟦0⟧
<h3>معادلهٔ دایره</h3>
⟦1⟧
<p>با بسط دادن، <b>شکل کلی</b> $x^2 + y^2 + Dx + Ey + F = 0$ به دست می‌آید که مرکز آن $\left(-\frac{D}{2}, -\frac{E}{2}\right)$ و شعاعش $r = \sqrt{\frac{D^2}{4} + \frac{E^2}{4} - F}$ است.</p>
⟦2⟧
<h3>وضعیت یک نقطه</h3>
<p>نقطه را در $(x - a)^2 + (y - b)^2$ جای‌گذاری کنید و با $r^2$ مقایسه کنید: کوچک‌تر ← درون، برابر ← روی دایره، بزرگ‌تر ← بیرون.</p>
<h3>مماس‌ها</h3>
<p>مماس در نقطهٔ تماس بر شعاع عمود است. برای دایرهٔ $x^2 + y^2 = r^2$ در $(x_1, y_1)$، شیب شعاع $\frac{y_1}{x_1}$ است، پس شیب مماس $-\frac{x_1}{y_1}$ است.</p>
<h3>سهمی‌ها</h3>
<p>$y^2 = 4px$ کانون $(p, 0)$ و خط هادی $x = -p$ دارد؛ $x^2 = 4py$ کانون $(0, p)$ و خط هادی $y = -p$ دارد. فاصلهٔ هر نقطهٔ سهمی از کانون برابر فاصلهٔ آن از خط هادی است.</p>
⟦3⟧`,
  'd8g3n0gso0': R`\text{وسط } \left(\frac{x_1 + x_2}{2}, \frac{y_1 + y_2}{2}\right) \qquad \text{فاصله } \sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}`,
  'yeziymovo4': R`$$(x - a)^2 + (y - b)^2 = r^2 \qquad \text{مرکز } (a, b), \text{ شعاع } r$$`,
  '16n3xjnynm7': R`<p>$x^2 + y^2 - 6x + 4y - 12 = 0$: با مربع کامل کردن، $(x - 3)^2 + (y + 2)^2 = 12 + 9 + 4 = 25$. مرکز $(3, -2)$، شعاع 5.</p>`,
  '11ib4pk61jv': R`<p>در $(x + 3)^2 + (y - 1)^2 = 16$ مرکز $(-3, 1)$ است — علامت‌ها برعکس می‌شوند — و شعاع 4 است، نه 16.</p>`,
  'a19ymany96': R`وسط پاره‌خط بین $⟦0⟧$ و $⟦1⟧$ را بیابید.`,
  'l7s72risy9': R`میانگین مختصات را بگیرید: $\left(\frac{⟦0⟧ + ⟦1⟧}{2}, \frac{⟦2⟧ + ⟦3⟧}{2}\right) = ⟦4⟧$.`,
  '1mu3r9x32jw': R`شعاع دایرهٔ $⟦0⟧ = 0$ را بیابید.`,
  '1bhxlcedykj': R`مربع کامل کنید: $(x ⟦0⟧)^2 + (y ⟦1⟧)^2 = ⟦2⟧ + ⟦3⟧ ⟦4⟧ = ⟦5⟧$، پس $r = ⟦6⟧$.`,
  'd11etx15kp': R`مرکز دایرهٔ $⟦0⟧ = 0$ را بیابید.`,
  '15nydo8wzsx': R`مرکز برابر است با $\left(-\frac{D}{2}, -\frac{E}{2}\right) = \left(-\frac{⟦0⟧}{2}, -\frac{⟦1⟧}{2}\right) = ⟦2⟧$.`,
  '10fdmgbsvjs': R`معادلهٔ دایره‌ای با مرکز $⟦0⟧$ و شعاع ⟦1⟧ کدام است؟`,
  'j31butbqt0': R`در $(x - a)^2 + (y - b)^2 = r^2$ جای‌گذاری کنید: $(x ⟦0⟧)^2 + (y ⟦1⟧)^2 = ⟦2⟧$.`,
  'qntj72wic0': R`درون دایره`,
  '1z2fjcjol1w': R`درون`,
  '1h4trl2qo1h': R`روی دایره`,
  '1sg9ogxwlev': R`روی`,
  '8uau8fsxbq': R`بیرون دایره`,
  '6gv2pbcp7q': R`بیرون`,
  '24luyo2ftju': R`آیا نقطهٔ $⟦0⟧$ درون، روی یا بیرون دایرهٔ $(x ⟦1⟧)^2 + (y ⟦2⟧)^2 = ⟦3⟧$ است؟`,
  '28keqi93flp': R`$⟦0⟧$ که برابر $r^2 = ⟦1⟧$ است: نقطه <b>روی</b> دایره است.`,
  '1hj2pbrwkr7': R`$⟦0⟧$ که کمتر از $r^2 = ⟦1⟧$ است: نقطه <b>درون</b> دایره است.`,
  'kv7senj1fr': R`$⟦0⟧$ که بیشتر از $r^2 = ⟦1⟧$ است: نقطه <b>بیرون</b> دایره است.`,
