  // linear-programming
  '23l7ef2fdyh': R`
<p><b>برنامه‌ریزی خطی</b> بهترین مقدار (بزرگ‌ترین یا کوچک‌ترین) یک <b>تابع هدف</b> خطی، مانند سود $z = 30x + 20y$، را با <b>قیدهای</b> خطی مانند $x + y \le 40$ پیدا می‌کند.</p>
<ol><li>قیدها را به صورت نامعادله بنویسید (همراه با $x \ge 0$ و $y \ge 0$).</li><li>هر خط مرزی را رسم کنید و ناحیه‌ای را که همهٔ قیدها را برآورده می‌کند سایه بزنید — <b>ناحیهٔ شدنی</b>.</li><li>رأس‌ها را با حل جفت‌جفتِ معادله‌های مرزی بیابید.</li><li>تابع هدف را در هر رأس حساب کنید.</li></ol>
⟦0⟧
⟦1⟧
<p>در مسئله‌های کمینه‌سازی با قیدهای «≥» ناحیه اغلب بی‌کران است؛ با هزینه‌های مثبت، کمینه باز هم در یک رأس رخ می‌دهد.</p>
⟦2⟧`,
  'hs1573xprv': R`<p><b>قضیهٔ رأس‌ها:</b> اگر مقدار بهینه وجود داشته باشد، در یکی از رأس‌های ناحیهٔ شدنی رخ می‌دهد.</p>`,
  '1g8qhbmqb9w': R`<p>$z = 3x + 2y$ را با قیدهای $x + y \le 8$، $2x + y \le 12$، $x, y \ge 0$ بیشینه کنید.</p><p>رأس‌ها: $(0, 0)$، $(6, 0)$، $(4, 4)$ [محل برخورد $x + y = 8$ و $2x + y = 12$]، $(0, 8)$.</p><p>مقدارهای $z$: 0, 18, 20, 16. بیشینه $z = 20$ در $(4, 4)$.</p>`,
  '11p3z90h4pd': R`<p>بررسی کنید که هر رأس <b>همهٔ</b> قیدها را برآورده کند — محل برخورد دو خط مرزی ممکن است بیرون ناحیه باشد.</p>`,
  '22hgo1z3v51': R`$z = ⟦0⟧ + ⟦1⟧$ را با قیدهای ⟦2⟧، $x \ge 0$، $y \ge 0$ بیشینه کنید. بیشترین مقدار $z$ چقدر است؟`,
  'thttp4dv20': R`رأس‌ها و مقدارهای $z$: ⟦0⟧. بیشینه <b>⟦1⟧</b> است.`,
  '2g9b1szo820': R`$z = ⟦0⟧ + ⟦1⟧$ را با قیدهای $x + y \ge ⟦2⟧$، $x + 2y \ge ⟦3⟧$، $x \ge 0$، $y \ge 0$ کمینه کنید. کمترین مقدار $z$ چقدر است؟`,
  '72m6dlh1yr': R`ناحیهٔ شدنی بی‌کران است و رأس‌هایش ⟦0⟧. چون هزینه‌ها مثبت‌اند، کمینه <b>⟦1⟧</b> است.`,
  '4eos6o7rio': R`کدام نقطه در ناحیهٔ شدنیِ تعریف‌شده با ⟦0⟧، $x \ge 0$، $y \ge 0$ قرار دارد؟`,
  '1jqzy1kt3ra': R`هر نقطه را در همهٔ قیدها بیازمایید. $⟦0⟧$ همهٔ آن‌ها را برآورده می‌کند؛ هر یک از نقطه‌های دیگر دست‌کم یکی را نقض می‌کند.`,
  '15d4uuzw5eq': R`یک نانوایی هر روز کیک ($x$) و پای ($y$) می‌پزد. حداکثر می‌تواند ⟦0⟧ عدد بپزد و زمان پخت قید ⟦1⟧ را می‌دهد. سود هر کیک ⟦2⟧ دلار و سود هر پای ⟦3⟧ دلار است. بیشترین سود روزانه چقدر است؟`,
  '296rrmt4h4q': R`قیدها: $x + y \le ⟦0⟧$، $⟦1⟧ \le ⟦2⟧$، $x, y \ge 0$. رأس‌ها: ⟦3⟧. بیشترین سود: <b>⟦4⟧</b> دلار.`,

  // logic
  '22xng4phovn': R`
<p><b>گزاره</b> جمله‌ای است که یا درست است یا نادرست. گزاره‌های مرکب با <b>رابط‌ها</b> ساخته می‌شوند:</p>
⟦0⟧
⟦1⟧
<h3>عکس، وارون و عکس نقیض</h3>
⟦2⟧
<h3>سورها</h3>
<p>$\forall$ «برای هر» و $\exists$ «وجود دارد». نقیض کردن آن‌ها را جابه‌جا می‌کند: نقیض «همهٔ دانش‌آموزان قبول شدند» می‌شود «<b>بعضی</b> دانش‌آموزان قبول <b>نشدند</b>»؛ نقیض «بعضی پرندگان نمی‌توانند پرواز کنند» می‌شود «همهٔ پرندگان می‌توانند پرواز کنند».</p>
<h3>استدلال‌های معتبر</h3>
<ul><li><b>وضع مقدم:</b> $p \Rightarrow q$، $p$؛ پس $q$.</li><li><b>رفع تالی:</b> $p \Rightarrow q$، $\neg q$؛ پس $\neg p$.</li><li><b>قیاس:</b> $p \Rightarrow q$، $q \Rightarrow r$؛ پس $p \Rightarrow r$.</li></ul>
⟦3⟧`,
